"""Render the human-readable score table from the versioned result data."""
from pathlib import Path
import json
CODE=Path(__file__).resolve().parents[1]
def clock(seconds):
 if seconds is None:return '—'
 return f'{int(seconds)//60}m {seconds%60:05.2f}s'
def main():
 dataset=json.loads((CODE/'data/results.json').read_text());rows=dataset['results'];cohort=json.loads((CODE/'data/cohort.json').read_text());labels=cohort['task_labels'];names=cohort['model_labels'];cutoff=str(json.loads((CODE/'gpu/scoring-policy.json').read_text())['speedup_threshold']);kernels=sorted([r for r in rows if r['task_id'].startswith('kernel-')],key=lambda r:(cohort['core_tasks'].index(r['task_id']),cohort['models'].index(r['model'])));observed=sum(r.get('benchmark_outcome')=='pass' for r in kernels);supported=sum(r.get('timing_supported_above_threshold') is True for r in kernels)
 lines=['# Initial benchmark results','','Kernel success now means a correct, source-compliant **measured speedup strictly greater than {cutoff}× versus baseline**. The GPT rows are a retrospective rescore of the original pilot (same sources, timings and timestamps; those actors pursued larger historical-reference targets). The Gemini 3.8 Flash rows use OpenCode (`opencode-v2`). The Claude rows are new trials under the same task snapshots, prompts, GPU dispatcher, judge and scoring policy, with a different inference client and host broker (`claude-cli-broker-linux-v1`; see below).','','**'+str(observed)+' of '+str(len(kernels))+' kernel cells exceed the measured cutoff; '+str(supported)+' also have a one-sided 95% timing lower bound above it.** All cutoff-crossing measurements also have timing lower bounds above {cutoff}×. The prefill measurements do not qualify. Two GPT-5.6 sources are AST-identical to the baseline; their small measured deviations are controls, not evidence of algorithmic progress. No Claude source is AST-identical to its baseline.','','One valid trial per model/task, high reasoning, with a 30-minute cap. Shared queue waits, infrastructure replacements, different cohort concurrency and different harnesses limit model comparisons.','','![Progress matrix](charts/recovery-matrix.png)','','## Kernel speedup and research time','','Time is the earliest in-budget checkpoint containing the exact final source that was evaluated. Earlier different source versions were not exhaustively evaluated, so this is **time to the measured final artifact**, not proof of the earliest possible speedup. Total trial duration and exact seconds remain in the JSON/CSV.','','| Task | Model | Measured speedup | Time to measured artifact | >{cutoff}× | 95% lower bound > cutoff | Source note |','|---|---|---:|---:|---|---|---|']
 for r in kernels:
  speed=r.get('speedup_vs_baseline');note='Unchanged baseline AST' if r.get('source_equals_baseline_ast') else ('Compilation failure' if r['benchmark_outcome']=='incorrect' else 'Reviewed source')
  lines.append('| '+labels[r['task_id']]+' | '+names[r['model']]+' | '+(f'{speed:.6f}×' if speed is not None else '—')+' | '+clock(r.get('time_to_measured_speedup_seconds'))+' | '+('Yes' if r['benchmark_outcome']=='pass' else 'No')+' | '+('Yes' if r.get('timing_supported_above_threshold') else ('No' if speed is not None else '—'))+' | '+note+' |')
 lines+=['','![Kernel measurements](charts/kernel-performance.png)','','The old “below target” label meant below our calibrated historical references (about 1.39×–2.45×), not necessarily slower than baseline. No candidate recovered those original reference targets. They remain a secondary metric in the JSON; the [original results](data/results-historical-target-v1.json), [original scoring policy](gpu/scoring-policy-historical-v1.json) and [calibration traces](data/calibrated-targets.json) are preserved.','','These are local H200 measurements, not official OKC leaderboard scores. The requested raw cutoff does not establish that tiny gains are real; timing support and unchanged-code controls are reported separately.','','## Integer multiplication','','| Model | Outcome | Time to admitted witness |','|---|---|---:|']
 for r in rows:
  if r['task_id']=='integer-mult-frame-retiming':lines.append('| '+names[r['model']]+' | '+r['benchmark_outcome']+' | '+clock(r.get('time_to_validated_breakthrough_seconds'))+' |')
 lines+=['','Integer admissions are exact finite conditional witnesses, with the trusted reference independently replayed through all eight mandatory stages. They do not prove inherited all-size compiler or analytic interfaces. GPT-5.6 reached the cap without a sealed submission. All three Claude models stopped before the cap without sealing a submission.','','![Integer recovery](charts/integer-recovery.png)','','## Additional mathematical trials','','| Task | Model | Evidence | Outcome |','|---|---|---|---|']
 for r in rows:
  if r['scope']=='additional_math':lines.append('| '+r['task_id']+' | '+names[r['model']]+' | '+r.get('evidence_class','none')+' | '+r['benchmark_outcome']+' |')
 lines+=['','## Claude models: harness differences','','The Claude rows use harness `claude-cli-broker-linux-v1`, recorded as a distinct harness version. Inference is the Claude Code CLI in print mode with every built-in tool disabled, no MCP servers and no settings or memory files; it returns the same `{command, done, note}` action through `--json-schema`, and any other tool event invalidates the trial. Commands run in a Linux namespace broker (uid 65534; fresh mount, network, pid, ipc and uts namespaces; read-only system directories and venv; read-write trial workspace only; no network) instead of macOS Seatbelt. Prompts are identical except “Your Mac shell” → “Your Linux shell”. GPU diagnostics, final two-bank evaluation, the judge and the scoring policy are unchanged; lease provisioning is retried up to three times as an infrastructure measure. Kernel trials ran five at a time on one shared H200 queue. Source audits for these rows were performed by the operating Claude session (diff review plus an AST scan for cross-call state, caching, file access and timer/checker patching).','','Earlier Claude attempts are excluded as infrastructure-invalid and listed in `infrastructure_exclusions`: two host-session suspensions that killed running trials, one cohort in which diagnostic results were unreadable by the sandboxed actor (a bug in the Linux port, since fixed) and one cohort hit by a Daytona H200 provisioning outage. Each was replaced by a fresh full-budget trial; no unsuccessful research outcome was replaced.']
 lines+=['','Quasi-RH admits exact arithmetic under H1–H5; unit-distance admits a conditional argument after non-formal curator review plus exact reference algebra checks. Neither is a complete formal theorem or a new headline exponent. Van der Waerden proof review and Sidorenko activation-geometry provenance remain unresolved and unscored.','','## Reproduce and inspect','','[Setup](README.md) · [Protocol](PROTOCOL.md) · [JSON](data/results.json) · [CSV](data/results.csv) · [Cohort metadata](data/cohort.json) · [Chart source](tools/chart.py) · [Table source](tools/render_results.py) · [GPU deletion accounting](data/gpu-lifecycle.json)','','Sealed kernel sources, two-bank measurements, mathematical proof hashes and integer witnesses are published. Private optimized reference sources and raw credential/client logs are excluded. Research isolation cannot eliminate historical training contamination. Four infrastructure-invalid attempts were excluded and replaced; these remain documented in the data.']
 (CODE/'RESULTS.md').write_text('\n'.join(line.replace('{cutoff}',cutoff) for line in lines)+'\n')
if __name__=='__main__':main()
